/*
 * INPUT:
 * $input.all() = existing rows from the selected Google Sheet tab.
 *
 * QUALIFIED LEADS:
 * Output 0 of "Route by Qualification Status".
 */

const existingRows = $input
  .all()
  .map(item => item.json);

const qualifiedLeads = $(
  'Route by Qualification Status'
)
  .all(0)
  .map(item => item.json);

/*
 * Return the first non-empty value found
 * from the supplied possible column names.
 */

function getValue(row, possibleNames) {
  for (const name of possibleNames) {
    const value = row?.[name];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

/*
 * Parse the Raw Row Data column when available.
 *
 * Some older sheet rows may have shifted columns,
 * while the correct original values remain inside
 * Raw Row Data as JSON.
 */

function parseRawRowData(row) {
  const possibleNames = [
    'Raw Row Data',
    'raw_row_data',
    'Raw Data',
    'raw_data',
    'rawRowData',
  ];

  for (const name of possibleNames) {
    const rawValue = row?.[name];

    if (
      rawValue === undefined ||
      rawValue === null ||
      rawValue === ''
    ) {
      continue;
    }

    if (
      typeof rawValue === 'object' &&
      !Array.isArray(rawValue)
    ) {
      return rawValue;
    }

    try {
      const parsed = JSON.parse(
        String(rawValue)
      );

      if (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }
    } catch {
      // Invalid Raw Row Data is safely ignored.
    }
  }

  return {};
}

/*
 * Check the normal row first.
 * If the value is missing, check Raw Row Data.
 */

function getValueFromBoth(
  row,
  rawRow,
  possibleNames
) {
  return (
    getValue(row, possibleNames) ||
    getValue(rawRow, possibleNames)
  );
}

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeEmail(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

function normalizeLinkedIn(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(
      /^https?:\/\/(www\.)?/,
      ''
    )
    .replace(/\/+$/, '');
}

function getFullName(row, rawRow = {}) {
  const directName =
    getValueFromBoth(
      row,
      rawRow,
      [
        'full_name',
        'Full Name',
        'Full name',
        'Name',
        'name',
      ]
    );

  if (directName) {
    return normalizeText(
      directName
    );
  }

  const firstName =
    getValueFromBoth(
      row,
      rawRow,
      [
        'first_name',
        'First name',
        'First Name',
        'firstname',
      ]
    );

  const lastName =
    getValueFromBoth(
      row,
      rawRow,
      [
        'last_name',
        'Last Name',
        'Last name',
        'lastname',
      ]
    );

  return normalizeText(
    `${firstName} ${lastName}`
  );
}

function getKeys(row) {
  const rawRow =
    parseRawRowData(row);

  const linkedin =
    normalizeLinkedIn(
      getValueFromBoth(
        row,
        rawRow,
        [
          'linkedin',
          'Linkedin',
          'LinkedIn',
          'LinkedIn URL',
          'linkedin_url',
          'linkedinUrl',
        ]
      )
    );

  const email =
    normalizeEmail(
      getValueFromBoth(
        row,
        rawRow,
        [
          'email',
          'Email',
          'Email Address',
          'work_email',
          'Work Email',
          'personal_email',
          'Personal Email',
        ]
      )
    );

  const fullName =
    getFullName(
      row,
      rawRow
    );

  const company =
    normalizeText(
      getValueFromBoth(
        row,
        rawRow,
        [
          'company_name',
          'company name',
          'Company Name',
          'Company',
          'company',
        ]
      )
    );

  const title =
    normalizeText(
      getValueFromBoth(
        row,
        rawRow,
        [
          'job_title',
          'title',
          'Title',
          'Job Title',
        ]
      )
    );

  return {
    linkedin,
    email,

    nameCompany:
      fullName && company
        ? `${fullName}|${company}`
        : '',

    nameTitle:
      fullName && title
        ? `${fullName}|${title}`
        : '',
  };
}

/*
 * Create lookup sets from all existing
 * Google Sheet rows.
 */

const existingLinkedIn =
  new Set();

const existingEmails =
  new Set();

const existingNameCompany =
  new Set();

const existingNameTitle =
  new Set();

for (const row of existingRows) {
  const keys = getKeys(row);

  if (keys.linkedin) {
    existingLinkedIn.add(
      keys.linkedin
    );
  }

  if (keys.email) {
    existingEmails.add(
      keys.email
    );
  }

  if (keys.nameCompany) {
    existingNameCompany.add(
      keys.nameCompany
    );
  }

  if (keys.nameTitle) {
    existingNameTitle.add(
      keys.nameTitle
    );
  }
}

/*
 * Compare qualified leads in the required order:
 *
 * 1. LinkedIn URL
 * 2. Email
 * 3. Full name + company
 * 4. Full name + title
 */

const newLeads = [];

for (const lead of qualifiedLeads) {
  const keys = getKeys(lead);

  let duplicateMatchedBy = '';

  if (
    keys.linkedin &&
    existingLinkedIn.has(
      keys.linkedin
    )
  ) {
    duplicateMatchedBy =
      'LinkedIn URL';
  } else if (
    keys.email &&
    existingEmails.has(
      keys.email
    )
  ) {
    duplicateMatchedBy =
      'Email';
  } else if (
    keys.nameCompany &&
    existingNameCompany.has(
      keys.nameCompany
    )
  ) {
    duplicateMatchedBy =
      'Full name and company';
  } else if (
    keys.nameTitle &&
    existingNameTitle.has(
      keys.nameTitle
    )
  ) {
    duplicateMatchedBy =
      'Full name and title';
  }

  /*
   * Existing lead:
   * do not return it.
   */

  if (duplicateMatchedBy) {
    continue;
  }

  /*
   * Immediately add accepted lead keys
   * to the lookup sets.
   *
   * This also prevents duplicates inside
   * the current qualified batch.
   */

  if (keys.linkedin) {
    existingLinkedIn.add(
      keys.linkedin
    );
  }

  if (keys.email) {
    existingEmails.add(
      keys.email
    );
  }

  if (keys.nameCompany) {
    existingNameCompany.add(
      keys.nameCompany
    );
  }

  if (keys.nameTitle) {
    existingNameTitle.add(
      keys.nameTitle
    );
  }

  newLeads.push({
    json: {
      ...lead,

      master_sheet_duplicate:
        false,

      master_sheet_duplicate_check:
        'Passed',

      next_step:
        'Check Monday.com CRM boards for duplicates',
    },
  });
}

return newLeads;

/*
 * Monday items are the direct input to this node.
 * Candidate leads are taken from:
 * "Remove Master Sheet Duplicates"
 */

const mondayItems = $input
  .all()
  .map(item => item.json);

const candidateLeads = $(
  'Remove Master Sheet Duplicates'
)
  .all()
  .map(item => item.json);

/*
 * Normalization helpers
 */

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/[^\p{L}\p{N}@.+:/\-\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeEmail(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

function normalizeLinkedIn(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/\/+$/, '');
}

function normalizeCompany(value) {
  return normalizeText(value)
    .replace(
      /\b(incorporated|inc|llc|ltd|limited|corp|corporation)\b/g,
      ''
    )
    .replace(/\s+/g, ' ')
    .trim();
}

/*
 * Read a Monday column by its visible title.
 *
 * Monday output contains:
 * item.name
 * item.column_values[].column.title
 * item.column_values[].text
 */

function getMondayColumn(item, wantedTitles) {
  const wanted = wantedTitles.map(
    title => normalizeText(title)
  );

  const columns = Array.isArray(
    item.column_values
  )
    ? item.column_values
    : [];

  const match = columns.find(column => {
    const title = normalizeText(
      column?.column?.title
    );

    return wanted.includes(title);
  });

  if (!match) {
    return '';
  }

  if (
    match.text !== undefined &&
    match.text !== null &&
    String(match.text).trim() !== ''
  ) {
    return String(match.text).trim();
  }

  /*
   * Fallback for columns where Monday puts
   * the useful information inside "value".
   */
  if (match.value) {
    try {
      const parsed =
        typeof match.value === 'string'
          ? JSON.parse(match.value)
          : match.value;

      return String(
        parsed?.email ??
        parsed?.text ??
        parsed?.url ??
        parsed?.label ??
        ''
      ).trim();
    } catch {
      return '';
    }
  }

  return '';
}

function getMondayFullName(item) {
  const firstName = getMondayColumn(
    item,
    ['First Name', 'First name']
  );

  const lastName = getMondayColumn(
    item,
    ['Last Name', 'Last name']
  );

  const combinedName = normalizeText(
    `${firstName} ${lastName}`
  );

  /*
   * Monday item.name is also the lead name,
   * so use it when First Name/Last Name are empty.
   */
  return combinedName ||
    normalizeText(item.name);
}

function getMondayKeys(item) {
  const fullName =
    getMondayFullName(item);

  const linkedin = normalizeLinkedIn(
    getMondayColumn(item, [
      'Linkedin',
      'LinkedIn',
      'LinkedIn URL',
    ])
  );

  const email = normalizeEmail(
    getMondayColumn(item, [
      'Email',
      'Email Address',
    ])
  );

  const company = normalizeCompany(
    getMondayColumn(item, [
      'Company',
      'Company Name',
    ])
  );

  const title = normalizeText(
    getMondayColumn(item, [
      'Title',
      'Job Title',
    ])
  );

  return {
    linkedin,
    email,

    nameCompany:
      fullName && company
        ? `${fullName}|${company}`
        : '',

    nameTitle:
      fullName && title
        ? `${fullName}|${title}`
        : '',
  };
}

function getCandidateFullName(lead) {
  const directName = normalizeText(
    lead.full_name ??
    lead['Full Name'] ??
    lead.name
  );

  if (directName) {
    return directName;
  }

  return normalizeText(
    `${
      lead.first_name ??
      lead['First Name'] ??
      ''
    } ${
      lead.last_name ??
      lead['Last Name'] ??
      ''
    }`
  );
}

function getCandidateKeys(lead) {
  const fullName =
    getCandidateFullName(lead);

  const linkedin = normalizeLinkedIn(
    lead.linkedin ??
    lead.LinkedIn ??
    lead.Linkedin ??
    lead['LinkedIn URL']
  );

  const email = normalizeEmail(
    lead.email ??
    lead.Email ??
    lead['Email Address']
  );

  const company = normalizeCompany(
    lead.company_name ??
    lead['company name'] ??
    lead['Company Name'] ??
    lead.Company
  );

  const title = normalizeText(
    lead.job_title ??
    lead.title ??
    lead.Title ??
    lead['Job Title']
  );

  return {
    linkedin,
    email,

    nameCompany:
      fullName && company
        ? `${fullName}|${company}`
        : '',

    nameTitle:
      fullName && title
        ? `${fullName}|${title}`
        : '',
  };
}

/*
 * Build lookup sets from all Monday items.
 */

const mondayLinkedIn = new Set();
const mondayEmails = new Set();
const mondayNameCompany = new Set();
const mondayNameTitle = new Set();

for (const item of mondayItems) {
  const keys = getMondayKeys(item);

  if (keys.linkedin) {
    mondayLinkedIn.add(keys.linkedin);
  }

  if (keys.email) {
    mondayEmails.add(keys.email);
  }

  if (keys.nameCompany) {
    mondayNameCompany.add(
      keys.nameCompany
    );
  }

  if (keys.nameTitle) {
    mondayNameTitle.add(
      keys.nameTitle
    );
  }
}

/*
 * Compare in the required order:
 *
 * 1. LinkedIn URL
 * 2. Email
 * 3. Full name + company
 * 4. Full name + title
 */

const newLeads = [];
const duplicateDetails = [];

for (const lead of candidateLeads) {
  const keys = getCandidateKeys(lead);

  let duplicateMatchedBy = '';

  if (
    keys.linkedin &&
    mondayLinkedIn.has(keys.linkedin)
  ) {
    duplicateMatchedBy =
      'LinkedIn URL';
  } else if (
    keys.email &&
    mondayEmails.has(keys.email)
  ) {
    duplicateMatchedBy =
      'Email';
  } else if (
    keys.nameCompany &&
    mondayNameCompany.has(
      keys.nameCompany
    )
  ) {
    duplicateMatchedBy =
      'Full name and company';
  } else if (
    keys.nameTitle &&
    mondayNameTitle.has(
      keys.nameTitle
    )
  ) {
    duplicateMatchedBy =
      'Full name and title';
  }

  /*
   * Duplicate exists in Monday:
   * skip it and do not send it to Google Sheets.
   */
  if (duplicateMatchedBy) {
    duplicateDetails.push({
      full_name:
        lead.full_name ?? '',
      company_name:
        lead.company_name ?? '',
      matched_by:
        duplicateMatchedBy,
    });

    continue;
  }

  /*
   * Add accepted leads to the sets immediately.
   * This also prevents duplicates inside the
   * current candidate batch.
   */

  if (keys.linkedin) {
    mondayLinkedIn.add(keys.linkedin);
  }

  if (keys.email) {
    mondayEmails.add(keys.email);
  }

  if (keys.nameCompany) {
    mondayNameCompany.add(
      keys.nameCompany
    );
  }

  if (keys.nameTitle) {
    mondayNameTitle.add(
      keys.nameTitle
    );
  }

  newLeads.push({
    json: {
      ...lead,

      monday_duplicate: false,
      monday_duplicate_check:
        'Passed',

      monday_items_checked:
        mondayItems.length,

      monday_duplicates_skipped:
        duplicateDetails.length,

      next_step:
        'Append to B2B Private Jet Leads sheet',
    },
  });
}

return newLeads;

const items = $input.all();

// Get qualified count directly from the sheet append node
let actuallyAddedToSheet = 0;
try {
  actuallyAddedToSheet = $('Append or update row in sheet').all().length || 0;
} catch (e) {
  actuallyAddedToSheet = 0;
}

const needsReview = items.filter(i => 
  i.json.qualification_status === 'Needs Review'
);

const rejected = items.filter(i => 
  i.json.qualification_status === 'Rejected'
);

const revenueRejected = rejected.filter(i =>
  (i.json.rejection_reasons || '').toLowerCase().includes('revenue')
);

const wrongIndustry = rejected.filter(i =>
  (i.json.rejection_reasons || '').toLowerCase().includes('unrelated industry')
);

const notAviation = rejected.filter(i =>
  (i.json.rejection_reasons || '').toLowerCase().includes('no reliable evidence')
);

return [{
  json: {
    status: "complete",
    icp: "Private Aviation",
    total_processed: items.length,
    actually_added_to_sheet: actuallyAddedToSheet,
    needs_review: needsReview.length,
    rejected: rejected.length,
    rejection_breakdown: {
      revenue_out_of_range: revenueRejected.length,
      wrong_industry: wrongIndustry.length,
      not_private_aviation: notAviation.length
    },
    sheet_updated: actuallyAddedToSheet > 0 ? "Yes" : "No",
    timestamp: new Date().toISOString()
  }
}];

// Get items from BOTH previous nodes by name
const sheetItems = $('Remove Master Sheet Duplicates').all().map(item => item.json);
const mondayItems = $('Remove Monday Duplicates').all().map(item => item.json);

// UNION - combine both arrays and remove only exact duplicates
const allItems = [...sheetItems, ...mondayItems];

const seen = new Set();
const union = [];

for (const lead of allItems) {
  // Create unique key using email + linkedin + company
  const email = (lead.email || '').toLowerCase().trim();
  const linkedin = (lead.linkedin || '').toLowerCase().trim();
  const company = (lead.company_name || '').toLowerCase().trim();
  const key = `${email}|${linkedin}|${company}`;

  if (!seen.has(key)) {
    seen.add(key);
    union.push({ json: lead });
  }
}

return union;

const config = $('Webhook').first().json.body ?? {};

const currentYear = new Date().getUTCFullYear();

function normalizeText(value) {
  return String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function normalizeLinkedIn(value) {
  return normalizeText(value)
    .split('?')[0]
    .split('#')[0]
    .replace(/^https?:\/\/(www\.)?linkedin\.com\//, 'linkedin.com/')
    .replace(/\/+$/, '');
}

function parseRevenue(lead) {
  const rawRevenue = String(lead.company_annual_revenue ?? '').replace(/[$,\s]/g, '');
  if (rawRevenue && Number.isFinite(Number(rawRevenue))) return Number(rawRevenue);

  const cleanRevenue = String(lead.company_annual_revenue_clean ?? '').trim().toUpperCase();
  const match = cleanRevenue.match(/^([\d.]+)\s*([KMB])?$/);
  if (!match) return NaN;

  const multiplier = { K: 1_000, M: 1_000_000, B: 1_000_000_000 }[match[2]] ?? 1;
  return Number(match[1]) * multiplier;
}

function uniqueReasons(reasons) {
  return [...new Set(reasons)];
}

const minimumRevenue = Number(config.minimum_revenue ?? 50_000_000);
const maximumRevenue = Number(config.maximum_revenue ?? 500_000_000);
const maximumEmployees = Number(config.maximum_employees ?? 50);

const priorityStates = new Set(
  (config.priority_states ?? ['Colorado', 'Utah', 'California', 'Vermont', 'Wyoming', 'New York', 'Florida']).map(normalizeText)
);

const reviewedLeads = [];

for (const item of $input.all()) {
  const lead = item.json;
  const rejectionReasons = [];
  const reviewReasons = [];
  const positiveSignals = [];

  const title = normalizeText(lead.job_title);
  const industry = normalizeText(lead.industry);
  const companyName = String(lead.company_name ?? '').trim();
  const companyState = String(lead.company_state ?? lead.state ?? '').trim();
  const country = normalizeText(lead.company_country ?? lead.country);
  const companySize = Number(lead.company_size);
  const revenue = parseRevenue(lead);
  const foundedYear = Number(lead.company_founded_year);

  const companyAge = Number.isFinite(foundedYear) && foundedYear > 1800 && foundedYear <= currentYear
    ? currentYear - foundedYear : null;

  const primaryCompanyText = [
    lead.company_name,
    lead.industry,
    lead.company_description,
    lead.headline,
    lead.company_domain,
  ].filter(Boolean).join(' ').toLowerCase();

  const keywordText = normalizeText(lead.keywords);

  // Decision-maker check for LUXURY TRAVEL
  const isDecisionMaker = /\b(founder|co-founder|ceo|president|owner|coo|cmo|head travel advisor|head of travel|head of concierge|head of marketing|head of partnerships|managing partner)\b/i.test(title);

  if (!isDecisionMaker) {
    rejectionReasons.push(
      'Contact is not Founder, CEO, President, Owner, COO, CMO, Head Travel Advisor, Head of Concierge, Marketing, or Partnerships'
    );
  }

  const excludedTitle = /\b(junior|assistant|coordinator|independent advisor|travel agent|hosted agent)\b/i.test(title);
  if (excludedTitle && !isDecisionMaker) {
    rejectionReasons.push('Contact has an excluded or non-decision-making role');
  }

  // Geography
  if (!['united states', 'us', 'usa'].includes(country)) {
    rejectionReasons.push('Company is not based in the United States');
  }

  // Revenue - $50M+ bookings
  if (!Number.isFinite(revenue)) {
    rejectionReasons.push('Company revenue is missing or invalid');
  } else if (revenue < minimumRevenue || revenue > maximumRevenue) {
    rejectionReasons.push('Company revenue is outside the required $50M-$500M range');
  }

  // Employees - 10-50 agents
  if (!Number.isFinite(companySize)) {
    reviewReasons.push('Employee count requires verification');
  } else if (companySize < 1 || companySize > maximumEmployees) {
    rejectionReasons.push('Company has more than the maximum 50 employees or has an invalid employee count');
  }

  // LUXURY TRAVEL AGENCY VERIFICATION
  const strongLuxuryTravelCore = /\b(luxury travel agency|luxury travel|luxury tour operator|boutique travel|boutique travel agency|luxury travel advisor|travel agency|travel advisor|tour operator|luxury tours|bespoke travel|premium travel|high-end travel|affluent travel|luxury vacations|luxury holiday|luxury cruise)\b/i.test(
    `${primaryCompanyText} ${keywordText}`
  );

  const luxuryTravelIndustry = /\b(leisure, travel|travel & tourism|hospitality|travel|tourism)\b/i.test(industry);

  const affluentClientSignal = /\b(affluent|high-net-worth|hnw|luxury|vip|elite|premium|exclusive|bespoke|ultra-high|wealthy|discerning|principals)\b/i.test(
    `${primaryCompanyText} ${keywordText}`
  );

  // Reject if not luxury travel
  if (!strongLuxuryTravelCore) {
    rejectionReasons.push(
      'No reliable evidence that the company is a boutique luxury travel agency or medium-sized luxury travel agency'
    );
  }

  // Exclude specific companies
  if (/\b(virtuoso|fora|black tomato)\b/i.test(companyName)) {
    rejectionReasons.push('Company is specifically excluded (Virtuoso, Fora, Black Tomato are too large)');
  }

  // Reject unrelated industries
  const unrelatedIndustry = /\b(pharmaceuticals|medical practice|health, wellness|construction|manufacturing|logistics|freight|trucking|railroad|oil|energy|textiles|retail|food & beverages|architecture|design|real estate brokerage|public relations|advertising|events services|coffee|beverages)\b/i.test(industry);

  if (unrelatedIndustry && !strongLuxuryTravelCore) {
    rejectionReasons.push('Company operates in an unrelated industry rather than luxury travel');
  }

  // Positive signals
  if (strongLuxuryTravelCore) positiveSignals.push('Strong luxury-travel-agency evidence');
  if (luxuryTravelIndustry) positiveSignals.push('Travel/hospitality industry');
  if (affluentClientSignal) positiveSignals.push('Affluent client access signal');
  if (Number.isFinite(revenue) && revenue >= minimumRevenue && revenue <= maximumRevenue) positiveSignals.push('Revenue is within $50M-$500M');
  if (Number.isFinite(companySize) && companySize >= 1 && companySize <= maximumEmployees) positiveSignals.push('Employee count is within 10-50 range');

  const isPriorityState = priorityStates.has(normalizeText(companyState));
  if (isPriorityState) positiveSignals.push('Located in a priority state');

  if (companyAge !== null && companyAge >= 5) positiveSignals.push('Established company');

  // Data completeness
  const requiredValues = [
    lead.full_name,
    lead.linkedin,
    lead.job_title,
    lead.company_name,
    lead.company_domain ?? lead.company_website,
    country,
  ];

  const requiredFieldsComplete = requiredValues.every(v => v !== undefined && v !== null && String(v).trim() !== '') &&
    Number.isFinite(revenue) && Number.isFinite(companySize);

  if (!requiredFieldsComplete) reviewReasons.push('One or more required lead fields are missing');

  // Scoring
  let leadScore = 0;
  if (isDecisionMaker) leadScore += 25;
  if (strongLuxuryTravelCore) leadScore += 30;
  if (affluentClientSignal) leadScore += 10;
  if (Number.isFinite(revenue) && revenue >= minimumRevenue && revenue <= maximumRevenue) leadScore += 15;
  if (Number.isFinite(companySize) && companySize >= 1 && companySize <= maximumEmployees) leadScore += 10;
  leadScore += isPriorityState ? 5 : 2;
  if (companyAge !== null && companyAge >= 5) leadScore += 5;
  else if (companyAge !== null) leadScore += 2;
  if (requiredFieldsComplete) leadScore += 5;

  leadScore = Math.min(100, leadScore);
  const leadGrade = leadScore >= 85 ? 'A' : leadScore >= 70 ? 'B' : 'C';

  const uniqueRejectionReasons = uniqueReasons(rejectionReasons);
  const uniqueReviewReasons = uniqueReasons(reviewReasons);

  let qualificationStatus;
  if (uniqueRejectionReasons.length > 0) {
    qualificationStatus = 'Rejected';
  } else if (!strongLuxuryTravelCore || uniqueReviewReasons.length > 0 || !requiredFieldsComplete || leadGrade !== 'A') {
    qualificationStatus = 'Needs Review';
  } else {
    qualificationStatus = 'Qualified';
  }

  const estimatedRevenueText = Number.isFinite(revenue) ? `$${(revenue / 1_000_000).toFixed(1)}M` : 'unconfirmed revenue';

  const companyTypeText = strongLuxuryTravelCore
    ? 'luxury travel agency'
