        ? `Reject because: ${uniqueRejectionReasons.join('; ')}.`
        : uniqueReviewReasons.length
          ? `Review because: ${uniqueReviewReasons.join('; ')}.`
          : 'Company and contact match the assigned ICP.'
    }`;

  reviewedLeads.push({
    json: {
      ...lead,
      revenue_numeric: revenue,
      company_age: companyAge,
      priority_state: isPriorityState,
      decision_maker_verified: isDecisionMaker,
