function parseRevenue(lead) {
  const rawRevenue = String(lead.company_annual_revenue ?? '').replace(/[$,\s]/g, '');

  if (rawRevenue && Number.isFinite(Number(rawRevenue))) {
    return Number(rawRevenue);
