/*
 * Return the first non-empty value found
 * from the supplied possible column names.
 */

function getValue(row, possibleNames) {
  for (const name of possibleNames) {
    const value = row?.[name];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

/*
 * Parse the Raw Row Data column when available.
 *
 * Some older sheet rows may have shifted columns,
 * while the correct original values remain inside
 * Raw Row Data as JSON.
 */

function parseRawRowData(row) {
  const possibleNames = [
    'Raw Row Data',
    'raw_row_data',
    'Raw Data',
    'raw_data',
    'rawRowData',
  ];

  for (const name of possibleNames) {
    const rawValue = row?.[name];

    if (
      rawValue === undefined ||
      rawValue === null ||
      rawValue === ''
    ) {
      continue;
    }

    if (
      typeof rawValue === 'object' &&
      !Array.isArray(rawValue)
    ) {
      return rawValue;
    }

    try {
      const parsed = JSON.parse(
        String(rawValue)
      );

      if (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }
    } catch {
      // Invalid Raw Row Data is safely ignored.
    }
  }

  return {};
}

/*
 * Check the normal row first.
 * If the value is missing, check Raw Row Data.
 */

function getValueFromBoth(
  row,
  rawRow,
  possibleNames
) {
  return (
    getValue(row, possibleNames) ||
    getValue(rawRow, possibleNames)
  );
}

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeEmail(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

function normalizeLinkedIn(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(
      /^https?:\/\/(www\.)?/,
      ''
    )
    .replace(/\/+$/, '');
}

function getFullName(row, rawRow = {}) {
  const directName =
    getValueFromBoth(
      row,
      rawRow,
      [
        'full_name',
        'Full Name',
        'Full name',
        'Name',
        'name',
      ]
    );

  if (directName) {
    return normalizeText(
      directName
    );
  }

  const firstName =
    getValueFromBoth(
      row,
      rawRow,
      [
        'first_name',
        'First name',
        'First Name',
        'firstname',
      ]
    );

  const lastName =
    getValueFromBoth(
      row,
      rawRow,
      [
        'last_name',
        'Last Name',
        'Last name',
        'lastname',
      ]
    );

  return normalizeText(
    `${firstName} ${lastName}`
  );
}

function getKeys(row) {
  const rawRow =
    parseRawRowData(row);

  const linkedin =
    normalizeLinkedIn(
      getValueFromBoth(
        row,
        rawRow,
        [
          'linkedin',
          'Linkedin',
          'LinkedIn',
          'LinkedIn URL',
          'linkedin_url',
          'linkedinUrl',
        ]
      )
    );

  const email =
    normalizeEmail(
      getValueFromBoth(
        row,
        rawRow,
        [
          'email',
          'Email',
          'Email Address',
          'work_email',
          'Work Email',
          'personal_email',
          'Personal Email',
        ]
      )
    );

  const fullName =
    getFullName(
      row,
      rawRow
    );

  const company =
    normalizeText(
      getValueFromBoth(
        row,
        rawRow,
        [
          'company_name',
          'company name',
          'Company Name',
          'Company',
          'company',
        ]
      )
    );

  const title =
    normalizeText(
      getValueFromBoth(
        row,
        rawRow,
        [
          'job_title',
          'title',
          'Title',
          'Job Title',
        ]
      )
    );

  return {
    linkedin,
    email,

    nameCompany:
      fullName && company
        ? `${fullName}|${company}`
        : '',

    nameTitle:
      fullName && title
        ? `${fullName}|${title}`
        : '',
  };
}

