);

const wrongIndustry = rejected.filter(i =>
  (i.json.rejection_reasons || '').toLowerCase().includes('unrelated industry')
);

const notAviation = rejected.filter(i =>
  (i.json.rejection_reasons || '').toLowerCase().includes('no reliable evidence')
);

return [{
  json: {
    status: "complete",
    icp: "Private Aviation",
    total_processed: items.length,
    actually_added_to_sheet: actuallyAddedToSheet,
    needs_review: needsReview.length,
    rejected: rejected.length,
    rejection_breakdown: {
      revenue_out_of_range: revenueRejected.length,
      wrong_industry: wrongIndustry.length,
      not_private_aviation: notAviation.length
    },
    sheet_updated: actuallyAddedToSheet > 0 ? "Yes" : "No",
    timestamp: new Date().toISOString()
  }
}];

// Get items from BOTH previous nodes by name
const sheetItems = $('Remove Master Sheet Duplicates2').all().map(item => item.json);
const mondayItems = $('Remove Monday Duplicates2').all().map(item => item.json);

// UNION - combine both arrays and remove only exact duplicates
const allItems = [...sheetItems, ...mondayItems];

const seen = new Set();
const union = [];

for (const lead of allItems) {
  // Create unique key using email + linkedin + company
  const email = (lead.email || '').toLowerCase().trim();
  const linkedin = (lead.linkedin || '').toLowerCase().trim();
  const company = (lead.company_name || '').toLowerCase().trim();
  const key = `${email}|${linkedin}|${company}`;

  if (!seen.has(key)) {
    seen.add(key);
    union.push({ json: lead });
  }
}

return union;

const config = $('Webhook').first().json.body ?? {};

/*
 * Helpers
 */

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/\s+/g, ' ');
}

function normalizeLinkedIn(value) {
  return normalizeText(value)
    .split('?')[0]
    .split('#')[0]
    .replace(
      /^https?:\/\/(www\.)?linkedin\.com\//,
      'linkedin.com/'
    )
    .replace(/\/+$/, '');
}

function parseRevenue(lead) {
  const rawRevenue = String(
    lead.company_annual_revenue ?? ''
  ).replace(/[$,\s]/g, '');

  if (
    rawRevenue &&
    Number.isFinite(Number(rawRevenue))
  ) {
    return Number(rawRevenue);
  }

  const cleanRevenue = String(
    lead.company_annual_revenue_clean ?? ''
  )
    .trim()
    .toUpperCase()
    .replace(/[$,\s]/g, '');

  const match = cleanRevenue.match(
    /^([\d.]+)([KMB])?$/
  );

  if (!match) {
    return NaN;
  }

  const multiplier = {
    K: 1_000,
    M: 1_000_000,
    B: 1_000_000_000,
  }[match[2]] ?? 1;

  return Number(match[1]) * multiplier;
}

function unique(values) {
  return [
    ...new Set(
      values.filter(Boolean)
    ),
  ];
}

function hasValue(value) {
  return (
    value !== undefined &&
    value !== null &&
    String(value).trim() !== ''
  );
}

/*
 * Resolve the B2C route sent by OpenClaw.
 */

const rawIcp = normalizeText(
  config.icp ??
  config.category ??
  'general'
).replace(/[\s-]+/g, '_');

const icpAliases = {
  realestate: 'real_estate',
  property: 'real_estate',
  property_development: 'real_estate',

  financial_services: 'finance',
  banking: 'finance',
  investment_management: 'finance',
  private_equity: 'finance',
  venture_capital: 'finance',

  technology: 'tech',
  software: 'tech',
  saas: 'tech',
  crypto: 'tech',
  cryptocurrency: 'tech',
};

const requestedIcp =
  icpAliases[rawIcp] ??
  rawIcp;

const minimumRevenue = Number(
  config.minimum_revenue ??
  20_000_000
);

const maximumRevenue = Number(
  config.maximum_revenue ??
  100_000_000
);

/*
 * Approved B2C geographies.
 */

const skiStates = new Set([
  'colorado',
  'california',
  'utah',
  'montana',
  'wyoming',
  'washington',
]);

const majorCities = new Set([
  'new york',
  'new york city',
  'miami',
  'san francisco',
  'los angeles',
  'austin',
  'dallas',
]);

/*
 * Industry rules for all three B2C paths.
 */

const industryRules = {
  real_estate: {
    label: 'B2C Real Estate',

    exact:
      /\b(real estate|property development|commercial property|commercial real estate|real estate investment|real estate development)\b/i,

    adjacent:
      /\b(property management|corporate housing|home inspection|relocation|mortgage|construction|architecture|brokerage|realtor|housing services)\b/i,
  },

  finance: {
    label: 'B2C Finance',

    exact:
      /\b(finance|financial services?|banking|investment management|asset management|wealth management|private equity|venture capital|fintech|investment firm|capital management)\b/i,

    adjacent:
      /\b(insurance|accounting|tax|mortgage|lending|payments?|credit)\b/i,
  },

  tech: {
    label: 'B2C Tech',

    exact:
      /\b(technology|software|saas|computer software|information technology|it services|internet|artificial intelligence|ai|cybersecurity|blockchain|crypto|cryptocurrency|cloud computing)\b/i,

    adjacent:
      /\b(digital agency|consulting|telecommunications|electronics|data services)\b/i,
  },

  general: {
    label: 'B2C Executive General',
    exact:
      /\b(professional services|business services)\b/i,
    adjacent: /.*/i,
  },
};

const rule =
  industryRules[requestedIcp] ??
  industryRules.general;

const reviewedLeads = [];

/*
 * Review every lead returned by Apify.
 */

for (const item of $input.all()) {
  const lead = item.json ?? {};

  const rejectionReasons = [];
  const reviewReasons = [];
  const positiveSignals = [];
  const missingInformation = [];

  const title = normalizeText(
    lead.job_title
  );

  const seniority = normalizeText(
    lead.seniority_level
  );

  const functionalLevel =
    normalizeText(
      lead.functional_level
    );

  const industry = normalizeText(
    lead.industry
  );

  const companyName = String(
    lead.company_name ?? ''
  ).trim();

  /*
   * For B2C, contact location is more important
   * than headquarters location.
   */

  const personCity = String(
    lead.city ??
    lead.company_city ??
    ''
  ).trim();

  const personState = String(
    lead.state ??
    lead.company_state ??
    ''
  ).trim();

  const country = normalizeText(
    lead.country ??
    lead.company_country
  );

  const isUS = [
    'united states',
    'us',
    'usa',
  ].includes(country);

  const companySize = Number(
    lead.company_size
  );

  const revenue =
    parseRevenue(lead);

  const primaryCompanyText = [
    lead.company_name,
    lead.industry,
    lead.company_description,
    lead.headline,
    lead.company_domain,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  const allPublicText = [
    primaryCompanyText,
    lead.keywords,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  /*
   * Target-title and ownership checks.
   */

  const founderOwnerTitle =
    /\b(founder|co[- ]?founder|owner|founding partner|managing partner|principal)\b/i.test(
      title
    );

  const executiveTitle =
    /\b(ceo|chief executive officer|president|coo|chief operating officer|cmo|chief marketing officer|cto|chief technology officer|investor|philanthropist|board member|chair|chairman|chairwoman)\b/i.test(
      title
    );

  const targetTitle =
    founderOwnerTitle ||
    executiveTitle;

  const ownershipEvidence =
    founderOwnerTitle ||
    /\b(founder|owner|partner)\b/i.test(
      seniority
    ) ||
    /\b(founder|co[- ]?founder|owner|equity partner|principal)\b/i.test(
      normalizeText(
        lead.headline
      )
    );

  const excludedTitle =
    /\b(sales representative|sales rep|sales executive|account executive|assistant|coordinator|analyst|associate|intern|realtor|real estate agent|broker|advisor|consultant|manager)\b/i.test(
      title
    );

  if (!targetTitle) {
    rejectionReasons.push(
      'Contact does not hold an approved B2C founder, owner, partner, or senior executive title'
    );
  }

  if (
    excludedTitle &&
    !founderOwnerTitle &&
    !executiveTitle
  ) {
    rejectionReasons.push(
      'Contact has a junior, sales, advisory, or non-owner role'
    );
  }

  /*
   * Generic C-suite alone is not enough.
   */

  if (
    targetTitle &&
    !ownershipEvidence
  ) {
    reviewReasons.push(
      'Senior title is present, but ownership, equity, or personal wealth evidence is not confirmed'
    );
  }

  /*
   * Country and revenue checks.
   */

  if (!isUS) {
    rejectionReasons.push(
      'Lead is not located in the United States'
    );
  }

  if (!Number.isFinite(revenue)) {
    reviewReasons.push(
      'Company revenue is missing or cannot be verified'
    );

    missingInformation.push(
      'Company revenue'
    );
  } else if (
    revenue < minimumRevenue ||
    revenue > maximumRevenue
  ) {
    rejectionReasons.push(
      'Company revenue is outside the required $20M-$100M range'
    );
  }

  /*
   * B2C has no fixed maximum employee rule,
   * but headcount is still scored.
   */

  if (
    !Number.isFinite(companySize) ||
    companySize <= 0
  ) {
    reviewReasons.push(
      'Employee headcount is missing or invalid'
    );

    missingInformation.push(
      'Employee headcount'
    );
  } else if (
    companySize > 1000
  ) {
    reviewReasons.push(
      'Company appears very large; verify that the person is an owner-led prospect without a full internal support team'
    );
  }

  /*
   * Industry qualification.
   */

  const exactIndustryMatch =
    rule.exact.test(industry) ||
    rule.exact.test(
      primaryCompanyText
    );

  const adjacentIndustryMatch =
    !exactIndustryMatch &&
    rule.adjacent.test(
      allPublicText
    );

  if (
    !exactIndustryMatch &&
    !adjacentIndustryMatch
  ) {
    rejectionReasons.push(
      `Company does not match the requested ${rule.label} industry`
    );
  } else if (
    adjacentIndustryMatch
  ) {
    reviewReasons.push(
      `Company appears adjacent to ${rule.label}; verify that it matches the assigned ICP`
    );
  }

  /*
   * Real-estate service providers may appear
   * in a real-estate search but are not always
   * genuine property investors/developers.
   */

  const ancillaryRealEstateService =
    requestedIcp ===
      'real_estate' &&
    /\b(home inspection|inspection company|realtor network|franchise network|corporate housing|relocation services|property maintenance)\b/i.test(
      primaryCompanyText
    );

  if (
    ancillaryRealEstateService
  ) {
    reviewReasons.push(
      'Company is an adjacent real-estate service rather than a clear property owner, developer, or investment business'
    );
  }

  /*
   * Geography.
   */

  const normalizedState =
    normalizeText(personState);

  const normalizedCity =
    normalizeText(personCity);

  const isSkiState =
    skiStates.has(
      normalizedState
    );

  const isMajorCity =
    majorCities.has(
      normalizedCity
    );

  const approvedLocation =
    isSkiState ||
    isMajorCity;

  if (
    !approvedLocation &&
    isUS
  ) {
    reviewReasons.push(
      'Location is in the US but outside the named ski states and major affluent cities'
    );
  }

  /*
   * Public fit signals.
   * Missing evidence is not treated as a negative fact.
   */

  const skiSignal =
    /\b(ski|skiing|winter travel|snow sports?|alpine)\b/i.test(
      allPublicText
    );

  const familyTravelSignal =
    /\b(family travel|family vacation|family trips?|travel with family)\b/i.test(
      allPublicText
    );

  const luxurySignal =
    /\b(luxury travel|private club|high[- ]?net[- ]?worth|hnw|private clients?|concierge|executive travel)\b/i.test(
      allPublicText
    );

  if (ownershipEvidence) {
    positiveSignals.push(
      'Founder, owner, partner, or equity signal'
    );
  }

  if (
    Number.isFinite(revenue) &&
    revenue >= minimumRevenue &&
    revenue <= maximumRevenue
  ) {
    positiveSignals.push(
      'Revenue is within $20M-$100M'
    );
  }

  if (approvedLocation) {
    positiveSignals.push(
      'Located in an approved ski state or affluent market'
    );
  }

  if (exactIndustryMatch) {
    positiveSignals.push(
      `Exact ${rule.label} industry match`
    );
  }

  if (skiSignal) {
    positiveSignals.push(
      'Public ski or winter-travel signal'
    );
  }

  if (familyTravelSignal) {
    positiveSignals.push(
      'Public family-travel signal'
    );
  }

  if (luxurySignal) {
    positiveSignals.push(
      'Public luxury, HNW, private-client, or concierge signal'
    );
  }

  /*
   * Required fields.
   */

  const requiredFields = {
    'Full name':
      lead.full_name,

    'LinkedIn URL':
      lead.linkedin,

    'Job title':
      lead.job_title,

    'Company name':
      lead.company_name,

    'Company website/domain':
      lead.company_domain ??
      lead.company_website,

    Location:
      personCity ||
      personState,
  };

  for (
    const [fieldName, value]
    of Object.entries(
      requiredFields
    )
  ) {
    if (!hasValue(value)) {
      missingInformation.push(
        fieldName
      );
    }
  }

  const requiredFieldsComplete =
    Object.values(
      requiredFields
    ).every(hasValue);

  if (!requiredFieldsComplete) {
    reviewReasons.push(
      'One or more required identity, company, or location fields are missing'
    );
  }

  /*
   * Existing B2C sheet scoring structure:
   *
   * Title:       20
   * Seniority:    7.5
   * Revenue:     12.5
   * Headcount:    7.5
   * Location:    10
   * Industry:     7.5
   *
   * Maximum raw points: 65
   * Raw points are normalized to 100.
   */

  let scoreTitle = 0;

  if (founderOwnerTitle) {
    scoreTitle = 20;
  } else if (
    /\b(ceo|chief executive officer|president)\b/i.test(
      title
    )
  ) {
    scoreTitle = 17.5;
  } else if (
    /\b(coo|chief operating officer|cmo|chief marketing officer|cto|chief technology officer|investor|philanthropist|board member|chair|chairman|chairwoman)\b/i.test(
      title
    )
  ) {
    scoreTitle = 15;
  }

  let scoreSeniority = 0;

  if (ownershipEvidence) {
    scoreSeniority = 7.5;
  } else if (
    seniority === 'c_suite' ||
    functionalLevel ===
      'c_suite' ||
    executiveTitle
  ) {
    scoreSeniority = 5;
  } else if (
    seniority === 'director' ||
    seniority === 'vp' ||
    seniority === 'head'
  ) {
    scoreSeniority = 2.5;
  }

  const scoreRevenue =
    Number.isFinite(revenue) &&
    revenue >= minimumRevenue &&
    revenue <= maximumRevenue
      ? 12.5
      : 0;

  let scoreHeadcount = 0;

  if (
    Number.isFinite(companySize) &&
    companySize >= 10 &&
    companySize <= 500
  ) {
    scoreHeadcount = 7.5;
  } else if (
    Number.isFinite(companySize) &&
    (
      (
        companySize >= 1 &&
        companySize < 10
      ) ||
      (
        companySize > 500 &&
        companySize <= 1000
      )
    )
  ) {
    scoreHeadcount = 5;
  } else if (
    Number.isFinite(companySize) &&
    companySize > 1000
  ) {
    scoreHeadcount = 2.5;
  }

  const scoreLocation =
    approvedLocation
      ? 10
      : isUS
        ? 5
        : 0;

  const scoreIndustry =
    exactIndustryMatch
      ? 7.5
      : adjacentIndustryMatch
        ? 3.75
        : 0;

  const totalPoints =
    scoreTitle +
    scoreSeniority +
    scoreRevenue +
    scoreHeadcount +
    scoreLocation +
    scoreIndustry;

  const maxPossiblePoints = 65;

  const normalizedScore =
    Number(
      (
        (
          totalPoints /
          maxPossiblePoints
        ) *
        100
      ).toFixed(1)
    );

  const leadGrade =
    normalizedScore >= 85
      ? 'A'
      : normalizedScore >= 70
        ? 'B'
        : 'C';

  const uniqueRejectionReasons =
    unique(
      rejectionReasons
    );

  const uniqueReviewReasons =
    unique(
      reviewReasons
    );

  const uniqueMissingInformation =
    unique(
      missingInformation
    );

  /*
   * Qualification status.
   */

  let qualificationStatus;

  if (
    uniqueRejectionReasons.length >
    0
  ) {
    qualificationStatus =
      'Rejected';
  } else if (
    uniqueReviewReasons.length >
      0 ||
    !requiredFieldsComplete ||
    leadGrade !== 'A'
  ) {
    qualificationStatus =
      'Needs Review';
  } else {
    qualificationStatus =
      'Qualified';
  }

  /*
   * Correct B2C sheet routing.
   */

  let destinationTab =
    'Needs Review Other Leads';

  if (
    qualificationStatus ===
    'Qualified'
  ) {
    if (
      requestedIcp ===
      'real_estate'
    ) {
      destinationTab =
        isSkiState
          ? 'B2C RE Ski States'
          : isMajorCity
            ? 'B2C RE Major Cities'
            : 'Needs Review Other Leads';
    } else if (
      requestedIcp ===
      'finance'
    ) {
      destinationTab =
        isSkiState
          ? 'B2C Finance Ski States'
          : isMajorCity
            ? 'B2C Finance Major Cities'
            : 'Needs Review Other Leads';
    } else {
      destinationTab =
        approvedLocation
          ? 'B2C Exec General'
          : 'Needs Review Other Leads';
    }
  }

  const revenueText =
    Number.isFinite(revenue)
      ? `$${(
          revenue /
          1_000_000
        ).toFixed(1)}M`
      : 'unconfirmed revenue';

  const publicSignalText =
    unique([
      skiSignal
        ? 'ski/winter travel'
        : '',

      familyTravelSignal
        ? 'family travel'
        : '',

      luxurySignal
        ? 'luxury/HNW/private-client access'
        : '',
    ]);

  /*
   * GPT Summary and SDR Note.
   */

  const gptSummary =
    `${lead.full_name ?? 'This contact'} is ${lead.job_title ?? 'a contact'} at ${companyName || 'an unidentified company'} in ${personCity || personState || 'an unconfirmed location'}. ` +
    `The company is reported at approximately ${revenueText} in annual revenue and ${Number.isFinite(companySize) ? companySize : 'an unconfirmed number of'} employees. ` +
    `${
      exactIndustryMatch
        ? `The company matches the ${rule.label} ICP.`
        : adjacentIndustryMatch
          ? `The company is adjacent to the ${rule.label} ICP and needs verification.`
          : `The company does not match the requested ${rule.label} ICP.`
    } ` +
    `${
      publicSignalText.length
        ? `Public signals found: ${publicSignalText.join(', ')}.`
        : 'No reliable public ski, family-travel, or luxury-travel signal was confirmed.'
    }`;

  const sdrNote =
    `Automated ${rule.label} lead from Apify. ` +
    `Status: ${qualificationStatus}; score ${normalizedScore}/100 (${leadGrade}). ` +
    `${
      uniqueRejectionReasons.length
        ? `Reject because: ${uniqueRejectionReasons.join('; ')}.`
        : uniqueReviewReasons.length
          ? `Review because: ${uniqueReviewReasons.join('; ')}.`
          : 'Strong title, revenue, industry, and location fit.'
    } ` +
    `Recommended tab: ${destinationTab}.`;

  const researchConfidence =
    uniqueMissingInformation.length ===
      0 &&
    Number.isFinite(revenue) &&
    Number.isFinite(companySize)
      ? 'High'
      : uniqueMissingInformation.length <=
          2
        ? 'Medium'
        : 'Low';

  reviewedLeads.push({
    json: {
      ...lead,

      revenue_numeric:
        revenue,

      requested_icp:
        requestedIcp,

      assigned_category:
        rule.label,

      destination_tab:
        destinationTab,

      ownership_or_equity_verified:
        ownershipEvidence,

      approved_b2c_location:
        approvedLocation,

      location_group:
        isSkiState
          ? 'Ski State'
          : isMajorCity
            ? 'Major Affluent City'
            : 'Other US Market',

      industry_match:
        exactIndustryMatch
          ? 'Exact'
          : adjacentIndustryMatch
            ? 'Adjacent'
            : 'No Match',

      required_fields_complete:
        requiredFieldsComplete,

      /*
       * Fields matching the B2C template.
       */

      score_title:
        scoreTitle,

      score_seniority:
        scoreSeniority,

      score_revenue:
        scoreRevenue,

      score_headcount:
        scoreHeadcount,

      score_location:
        scoreLocation,

      score_industry:
        scoreIndustry,

      total_points:
        totalPoints,

      max_possible_points:
        maxPossiblePoints,

      normalized_score:
        normalizedScore,

      lead_score:
        normalizedScore,

      lead_grade:
        leadGrade,

      fit_score:
        Math.max(
          1,
          Math.min(
            10,
            Math.round(
              normalizedScore /
              10
            )
          )
        ),

      qualification_status:
        qualificationStatus,

      rejection_reasons:
        uniqueRejectionReasons.join(
          '; '
        ),

      review_reasons:
        uniqueReviewReasons.join(
          '; '
        ),

      missing_information:
        uniqueMissingInformation.join(
          '; '
        ),

      fit_notes:
        unique(
          positiveSignals
        ).join('; '),

      research_confidence:
        researchConfidence,

      gpt_summary:
        gptSummary,

      sdr_note:
        sdrNote,

      lead_source:
        'Apify',

      added_by:
        config.added_by ??
        'OpenClaw',

      date_added:
        new Date()
          .toISOString()
          .slice(0, 10),

      /*
       * Duplicate checking happens in later nodes,
       * so the lead is not marked Ready here.
       */

      duplicate_check_status:
        'Pending',

      next_step:
        qualificationStatus ===
          'Qualified'
          ? 'Check Monday.com and the B2C master sheet for duplicates, then append to the recommended tab'
          : qualificationStatus ===
              'Needs Review'
            ? 'Manually verify ownership, company fit, missing information, and destination tab'
            : 'Do not add to an active B2C working tab',
    },
  });
}

/*
 * Remove duplicates inside this Apify batch.
 * This does not replace the later sheet and
 * Monday.com duplicate checks.
 */

const bestByPerson =
  new Map();

for (
  const item
  of reviewedLeads
) {
  const lead = item.json;

  const linkedIn =
    normalizeLinkedIn(
      lead.linkedin
    );

  const email =
    normalizeText(
      lead.email
    );

  const nameCompany = [
    normalizeText(
      lead.full_name
    ),
    normalizeText(
      lead.company_name
    ),
  ].join('|');

  const nameTitle = [
    normalizeText(
      lead.full_name
    ),
    normalizeText(
      lead.job_title
    ),
  ].join('|');

  const personKey =
    linkedIn
      ? `linkedin:${linkedIn}`
      : email
        ? `email:${email}`
        : nameCompany !== '|'
          ? `name-company:${nameCompany}`
          : `name-title:${nameTitle}`;

  const existing =
    bestByPerson.get(
      personKey
    );

  if (
    !existing ||
    Number(
      lead.lead_score
    ) >
      Number(
        existing.json.lead_score
      )
  ) {
    bestByPerson.set(
      personKey,
      item
    );
  }
}

const statusPriority = {
  Qualified: 1,
  'Needs Review': 2,
  Rejected: 3,
};

return [
  ...bestByPerson.values(),
].sort((a, b) => {
  const statusDifference =
    (
      statusPriority[
        a.json
          .qualification_status
      ] ?? 99
    ) -
    (
      statusPriority[
        b.json
          .qualification_status
      ] ?? 99
    );

  if (
    statusDifference !== 0
  ) {
    return statusDifference;
  }

  return (
    Number(
      b.json.lead_score
    ) -
    Number(
      a.json.lead_score
    )
  );
});
